// Package contract holds Go types for specs/common/v1, shared by every package
// that reads or writes a Privometry contract. Most of it is generated by
// scripts/gen-types; this file is written by hand.
package contract

import (
	"encoding/json"
	"fmt"
	"time"
)

// TimeLayout is the contract timestamp format: RFC 3339 in UTC with exactly
// three fractional digits.
const TimeLayout = "2006-01-02T15:04:05.000Z"

// Time is a timestamp that always marshals in TimeLayout. time.Time's own
// encoding drops trailing zeros and keeps offsets, which the schemas reject.
type Time struct{ time.Time }

// At wraps t, converted to UTC and truncated to milliseconds.
func At(t time.Time) Time { return Time{t.UTC().Truncate(time.Millisecond)} }

// String formats t in TimeLayout.
func (t Time) String() string { return t.UTC().Format(TimeLayout) }

// MarshalJSON implements json.Marshaler.
func (t Time) MarshalJSON() ([]byte, error) { return json.Marshal(t.String()) }

// UnmarshalJSON accepts any RFC 3339 time; producers must still emit TimeLayout.
func (t *Time) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err != nil {
		return err
	}
	parsed, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		return fmt.Errorf("contract: timestamp %q: %w", s, err)
	}
	*t = At(parsed)
	return nil
}
